% BLOCK 0 + FIRST DIFFERENTIATOR + SECOND DIFFERENTIATOR, as one continuous script
%
% Block 0 (adapter):  EV signal activates ADNCYC, then
%   ATP --ADNCYC--> cAMP --PDE1--> AMP --NTD7--> adenosine --PUNP1--> ribose-1-P
%       --PYNP2r (reverse)--> uridine --r1156--> UMP = m_in
% Differentiator 1 (inverted polarity: the output rises while m_in falls):
%   slow branch   m_in --r_S--> m_S --r_Sr--> m_d1          (output, produced late)
%   fast branch   m_in --r_F--> m_F --r_Fr--> products
%   cancellation  m_F + m_d1 --r_I--> products
% Differentiator 2 (the topology of the figure, output = fast branch), fed by m_d1:
%   fast branch   m_d1 --r_F_2--> m_d2 --r_Fr_2--> products  (m_d2 = output)
%   slow branch   m_d1 --r_S_2--> m_S2 --r_Sr_2--> products  (m_S2 = memory)
%   cancellation  m_S2 + m_d2 --r_I_2--> products
%   Connection to differentiator 1, chosen with consuming_2:
%     false  m_d1 only ACTIVATES r_F_2 and r_S_2, which work on a buffered
%            substrate. m_d1 is not consumed: no load on differentiator 1.
%     true   r_F_2 and r_S_2 CONSUME m_d1: they are the load on differentiator 1.
%   Regime, chosen with threshold_2:
%     false  proportional: m_d2 rests at a finite level and moves around it.
%     true   r_I_2 works at its maximum rate with respect to m_d2 (zero order),
%            so it SUBTRACTS the memory from the fast branch: m_d2 rests near
%            zero and shows only the positive pulses. Needs an ASSUMED, very
%            small K_M of r_I_2 for m_d2 (see section 5).
%
% Units: concentrations and Km in mM, V in mM/s, kcat and k in 1/s, time in s.
% Rates are Michaelis-Menten; all pools are advanced with explicit Euler, one
% step per input sample. Initial pools are the equilibrium for the first EV
% sample, so the traces show only the response to the input.
%
% Needs Parameters.m, Dataset_cell2cell.mat and kinetics_BRENDA.xlsx.
clc;
% clearvars;
close all;

addingPathParentFolderByName('code'); %[output:0cddb249]
Parameters                               % provides dt0 and fontsize
%%
%[text] ## 1. Input data
% load Dataset_cell2cell.mat
Dataset  = rmmissing(Dataset);
dist     = table2array(Dataset(:,1));
vesicles = table2array(Dataset(:,2:end));

row = 1;                                 % distance analysed in detail
N = size(vesicles,2);
t = (0:N-1)'*dt0;
assert(N >= 3 && all(isfinite(vesicles(row,:))) && all(vesicles(row,:) >= 0) && vesicles(row,1) > 0, ...
    'Use a finite nonnegative EV signal with a positive first sample.');
%%
%[text] ## 2. Enzyme constants from the BRENDA workbook
% Sheet "values" of kinetics_BRENDA.xlsx: reaction label in column B, and the
% columns K_M [mM], SA [umol/min/mg] and MW [mg/umol] found by their titles.
% kcat [1/s] = SA*MW/60.
raw = readcell('kinetics_BRENDA.xlsx','Sheet','values');
isText = @(x) ischar(x) || (isstring(x) && isscalar(x) && ~ismissing(x));
hdrRow = find(any(cellfun(@(x) isText(x) && startsWith(string(x),"K_M"),raw),2),1);
assert(~isempty(hdrRow),'Header row (a cell starting with "K_M") not found in the workbook.');
colOf = @(title) find(cellfun(@(x) isText(x) && startsWith(string(x),title),raw(hdrRow,:)),1);
colKM = colOf("K_M");  colSA = colOf("SA");  colMW = colOf("MW");

reactionNames = {'r_S','r_Sr','r_F','r_Fr','r_I'};

KM = nan(1,5);  kcat = nan(1,5);
for i = 1:5
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames{i});
    KM(i)   = raw{r,colKM};
    kcat(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM kcat])) && all([KM kcat] > 0),'K_M, SA and MW of the five reactions must be positive numbers.');

KM_S  = KM(1);  kcat_S  = kcat(1);       % r_S :  m_in -> m_S
KM_Sr = KM(2);  kcat_Sr = kcat(2);       % r_Sr:  m_S  -> m_d1
KM_F  = KM(3);  kcat_F  = kcat(3);       % r_F :  m_in -> m_F
KM_Fr = KM(4);  kcat_Fr = kcat(4);       % r_Fr:  m_F  -> products
KM_I  = KM(5);  kcat_I  = kcat(5);       % r_I :  m_F + m_d1 -> products
% r_I has two substrates. BRENDA's K_M is for the fast-pool substrate (m_F);
% the K_M for m_d1 is not in the table and is set equal to it here.
KM_I_Y = KM_I;

% Second differentiator: the same sheet, rows with these labels.
reactionNames2 = {'r_S_2','r_Sr_2','r_F_2','r_I_2','r_Fr_2'};
KM2 = nan(1,5);  kcat2 = nan(1,5);
for i = 1:5
    r = find(cellfun(@(x) isText(x) && strcmp(strtrim(char(x)),reactionNames2{i}),raw(:,2)),1);
    assert(~isempty(r),'Reaction %s not found in column B of the workbook.',reactionNames2{i});
    KM2(i)   = raw{r,colKM};
    kcat2(i) = raw{r,colSA}*raw{r,colMW}/60;
end
assert(all(isfinite([KM2 kcat2])) && all([KM2 kcat2] > 0),'K_M, SA and MW of the five D2 reactions must be positive numbers.');
KM_S_2  = KM2(1);  kcat_S_2  = kcat2(1);   % r_S_2 : m_d1 -> m_S2
KM_Sr_2 = KM2(2);  kcat_Sr_2 = kcat2(2);   % r_Sr_2: m_S2 -> products
KM_F_2  = KM2(3);  kcat_F_2  = kcat2(3);   % r_F_2 : m_d1 -> m_d2
KM_I_2  = KM2(4);  kcat_I_2  = kcat2(4);   % r_I_2 : m_S2 + m_d2 -> products
KM_Fr_2 = KM2(5);  kcat_Fr_2 = kcat2(5);   % r_Fr_2: m_d2 -> products
% As for r_I, the K_M of r_I_2 for its second substrate (m_d2) is assumed equal.
KM_I_2_Y = KM_I_2;

% ---- TEST: matched K_M pairs ----
% The output of a differentiator rests at a level that does not depend on its
% input only if the two reactions that compete for the same pool see it with
% the same K_M. Then their rates stay proportional at any saturation, and the
% cancellation by r_I is exact:
%   m_in : r_S   and r_F      (KM_S    = KM_F)
%   m_F  : r_Fr  and r_I      (KM_I    = KM_Fr)
%   m_S2 : r_Sr_2 and r_I_2   (KM_I_2  = KM_Sr_2)
% matched_KM = true overwrites three workbook values to show this. They are
% NOT measurements. false = workbook values as read.
matched_KM = true;
if matched_KM
    KM_S   = KM_F;                       % 0.0125 -> KM_F
    KM_I   = KM_Fr;                      % K_M of r_I for m_F   -> KM_Fr
    KM_I_2 = KM_Sr_2;                    % K_M of r_I_2 for m_S2 -> KM_Sr_2
    KM_Sr  = KM_Fr;                      % kept from your earlier test (does not affect the resting level)
end
%%
%[text] ## 3. Design choices
Delta_t = 30;                             % relative delay slow - fast branch [s]
W_X     = 1/600;                          % input bandwidth [rad/s]
E_max   = 0.02;                          % largest feasible enzyme concentration [mM] (20 uM)
w_S = 1;  w_F = 1;                       % branch gains
p_F = 1;                                 % folding probability
k_I_fast = 0;                            % rate of r_I on the fast pool assumed by Algorithm 1 [1/s]
E_max_I = E_max;                         % limit used for r_I [mM]; raise it to test (e.g. 0.3)

% Second differentiator
connect_D2    = true;                    % false = differentiator 1 unloaded, as before
consuming_2   = true;                   % false = m_d1 activates the D2 sources and is NOT consumed
%                                          true  = the D2 sources consume m_d1 (load on D1)
load_fraction = 0.01;                    % consuming only: share of the m_d1 removal taken by D2 at rest
sat_2         = 0.1;                     % non-consuming only: memory pool m_S2 at rest, as a fraction
%                                          of the smallest K_M it meets (sets the D2 fluxes)
KA_factor_2   = 10;                      % non-consuming only: activation constant K_A = KA_factor_2*Y1_target
rho_2         = 2;                       % memory flux / direct flux, v_S_2/v_F_2; must exceed 1
tau_S2        = 60;                      % memory time constant = delay of D2 [s]
tau_Y2        = 30;                      % output time constant of D2 [s] (threshold: set by r_Fr_2)
threshold_2   = true;                    % true = m_d2 rests near zero, positive pulses only (see header)
cleanup_2     = 1e-5;                    % share of the m_d2 production removed by r_Fr_2 at rest; r_I_2
%                                          removes the rest. Threshold regime: this is how exactly r_I_2
%                                          balances r_F_2, and it sets the resting m_d2. Must be > 0 there.
KMY_factor_2  = 1e-4;                    % threshold only: ASSUMED K_M of r_I_2 for m_d2, as a fraction of
%                                          the resting m_d2 (not the BRENDA value)
E_max_I_2     = E_max;                   % limit used for r_I_2 [mM]; raise it to test (e.g. 0.3)
%%
%[text] ## 4. Algorithm 1: enzyme concentrations of r\_S, r\_Sr, r\_F and r\_Fr
% Every rate constant is k = p_F*[E]*kcat/KM, so tau = 1/k_r and w = k_f/k_r.
tau_S_max = 0.1/W_X;                     % "W_X*tau_S << 1" taken as W_X*tau_S <= 0.1
tau_S = 2*Delta_t;                       % line 1: starting value, tau_S > Delta_t
feasible = false;
for iteration = 1:1000                   % lines 2-11: repeat ... until feasible
    alpha = 1-Delta_t/tau_S;                              % line 3
    tau_F = alpha*tau_S;
    E_Sr  = KM_Sr/(p_F*kcat_Sr*tau_S);                    % line 4: slow-branch removal
    k_Fr  = max(1/tau_F-k_I_fast,0);                      % line 5: fast pool removed by r_Fr and r_I
    E_Fr  = KM_Fr*k_Fr/(p_F*kcat_Fr);                     % line 6: fast-branch removal
    E_S   = w_S*KM_S/(p_F*kcat_S*tau_S);                  % line 7: k_f = w*k_r
    E_F   = w_F*KM_F/(p_F*kcat_F*tau_F);
    if all([E_S E_Sr E_F E_Fr] <= E_max)                  % line 8
        feasible = true;
        break
    end
    if tau_S < tau_S_max                                  % line 9: increase tau_S ...
        tau_S = min(1.1*tau_S,tau_S_max);
    elseif Delta_t > 1e-3*tau_S                           %         ... or reduce Delta_t
        Delta_t = 0.9*Delta_t;
    else
        break
    end
end
if ~feasible
    warning('Algorithm 1 found no set below E_max = %.3g uM; using the closest one.',1e3*E_max);
end
fprintf('Algorithm 1: tau_S = %.3g s, tau_F = %.3g s, Delta_t = %.3g s, alpha = %.3g, W_X*tau_S = %.3g\n', ... %[output:group:16491439] %[output:949a93d2]
    tau_S,tau_F,Delta_t,alpha,W_X*tau_S); %[output:group:16491439] %[output:949a93d2]

V_S  = kcat_S*E_S;
V_Sr = kcat_Sr*E_Sr;
V_F  = kcat_F*E_F;
V_Fr = kcat_Fr*E_Fr;
%%
%[text] ## 5. Operating point and enzyme concentration of r\_I
% Input level: a tenth of the smaller Km, so that r_S and r_F both work in
% their linear range.
m_in_target = 0.000125;%min(KM_S,KM_F)/10;
j_S_ref = V_S*m_in_target/(KM_S+m_in_target);            % basal slow flux
j_F_ref = V_F*m_in_target/(KM_F+m_in_target);            % basal fast flux

% r_I: enzyme amount that places the basal output at Y1_target. At
% equilibrium  v_I = j_S - load  and  v_Fr = j_F - v_I, which fixes m_F.
Y1_target = m_in_target;                 % gain 1 from m_in to m_d1

% ---- Second differentiator: its two source reactions ----
assert(rho_2 > 1 && load_fraction >= 0 && load_fraction < 1 && cleanup_2 >= 0 && cleanup_2 < 1 && sat_2 > 0,'Invalid D2 design choices.');
consume = double(connect_D2 && consuming_2);               % 1 = D2 withdraws m_d1
if consuming_2
    % m_d1 is the substrate. D2 removes it with rate constant k_load; r_I
    % removes it with 1/tau_out, tau_out = Y1_target/j_S_ref.
    Kx_F_2 = KM_F_2;  Kx_S_2 = KM_S_2;                     % constant met by m_d1
    k_load = connect_D2*load_fraction*j_S_ref/Y1_target;   % [1/s]
    k_F_2  = k_load/(1+rho_2);                             % direct branch
    k_S_2  = rho_2*k_F_2;                                  % memory branch
    E_F_2  = k_F_2*KM_F_2/(p_F*kcat_F_2);
    E_S_2  = k_S_2*KM_S_2/(p_F*kcat_S_2);
else
    % m_d1 is an activator: rate = V * m_d1/(K_A+m_d1), substrate buffered.
    % The same K_A for both sources, so that they stay proportional.
    % The fluxes are free, and are chosen so that the memory pool sits at
    % sat_2 times the smallest K_M it meets (r_Sr_2 and r_I_2).
    K_A_2  = KA_factor_2*Y1_target;
    Kx_F_2 = K_A_2;  Kx_S_2 = K_A_2;
    S2_wanted = sat_2*min(KM_Sr_2,KM_I_2);
    act_ref   = Y1_target/(K_A_2+Y1_target);               % activation at rest
    E_S_2  = connect_D2*(S2_wanted/tau_S2)/act_ref/(p_F*kcat_S_2);
    E_F_2  = E_S_2*kcat_S_2/(rho_2*kcat_F_2);
end
V_F_2 = kcat_F_2*E_F_2;  V_S_2 = kcat_S_2*E_S_2;
j_F_2_ref = V_F_2*Y1_target/(Kx_F_2+Y1_target);            % basal direct flux
j_S_2_ref = V_S_2*Y1_target/(Kx_S_2+Y1_target);            % basal memory flux
load_ref  = consume*(j_F_2_ref+j_S_2_ref);                 % what D2 withdraws from m_d1

% At rest: v_I_2 + v_Fr_2 = j_F_2 (output) and v_Sr_2 + v_I_2 = j_S_2 (memory).
if threshold_2
    % r_Fr_2 alone sets the output time constant; it holds only the small
    % share cleanup_2 of the production, so the resting m_d2 is near zero.
    assert(cleanup_2 > 0,'The threshold regime needs cleanup_2 > 0 (r_Fr_2 must be present).');
    Y2_target = cleanup_2*j_F_2_ref*tau_Y2;
    KM_I_2_Y  = KMY_factor_2*Y2_target;                    % ASSUMED: r_I_2 saturated in m_d2
else
    Y2_target = j_F_2_ref*tau_Y2;                          % output pool, time constant tau_Y2
end
S2_target = j_S_2_ref*tau_S2;                              % memory pool, time constant tau_S2
vFr_2_ref = cleanup_2*j_F_2_ref;
vI_2_ref  = j_F_2_ref-vFr_2_ref;
vSr_2_ref = j_S_2_ref-vI_2_ref;
E_Sr_2 = 0;  E_I_2 = 0;  E_Fr_2 = 0;
if connect_D2
    E_Sr_2 = vSr_2_ref*(KM_Sr_2+S2_target)/S2_target/kcat_Sr_2;
    E_Fr_2 = vFr_2_ref*(KM_Fr_2+Y2_target)/Y2_target/kcat_Fr_2;
    E_I_2  = vI_2_ref/(kcat_I_2*(S2_target/(KM_I_2+S2_target))*(Y2_target/(KM_I_2_Y+Y2_target)));
    if E_I_2 > E_max_I_2
        warning(['r_I_2 would need %.3g uM to hold m_d2 at %.3g mM; it is limited to %.3g uM, ' ...
            'so the basal m_d2 will be higher and slower.'],1e3*E_I_2,Y2_target,1e3*E_max_I_2);
        E_I_2 = E_max_I_2;
    end
end
if E_Fr_2 > E_max
    warning('r_Fr_2 needs %.3g uM for tau_Y2 = %.3g s (limit %.3g uM); a longer tau_Y2 needs less.', ...
        1e3*E_Fr_2,tau_Y2,1e3*E_max);
end
V_Sr_2 = kcat_Sr_2*E_Sr_2;  V_I_2 = kcat_I_2*E_I_2;  V_Fr_2 = kcat_Fr_2*E_Fr_2;
if connect_D2 && threshold_2 %[output:group:4cd60185]
    fprintf('D2 threshold regime: K_M of r_I_2 for m_d2 ASSUMED %.3g mM (workbook value for its other substrate: %.3g mM).\n', ... %[output:54250e7b]
        KM_I_2_Y,KM2(4)); %[output:54250e7b]
end %[output:group:4cd60185]

% ---- r_I of differentiator 1, with the load of D2 included ----
vI_ref  = j_S_ref-load_ref;
vFr_ref = j_F_ref-vI_ref;
assert(vI_ref > 0,'The load alone removes more than the slow branch produces; reduce load_fraction.');
assert(vFr_ref > 0 && vFr_ref < V_Fr, ...
    'The fast branch cannot supply r_I: its basal flux must exceed that of r_I and stay below V_Fr.');
m_F_ref = KM_Fr*vFr_ref/(V_Fr-vFr_ref);
E_I = vI_ref/(kcat_I*(m_F_ref/(KM_I+m_F_ref))*(Y1_target/(KM_I_Y+Y1_target)));
if E_I > E_max_I
    warning(['r_I would need %.3g uM to hold the basal output at %.3g mM; it is limited to ' ...
        '%.3g uM, so the basal output will be higher (see the diagnostics).'], ...
        1e3*E_I,Y1_target,1e3*E_max_I);
    E_I = E_max_I;
end
V_I = kcat_I*E_I;

reaction_parameters = table( ...
    {'r_S';'r_Sr';'r_F';'r_Fr';'r_I'}, ...
    [KM_S;KM_Sr;KM_F;KM_Fr;KM_I], ...
    [kcat_S;kcat_Sr;kcat_F;kcat_Fr;kcat_I], ...
    1e3*[E_S;E_Sr;E_F;E_Fr;E_I], ...
    [V_S;V_Sr;V_F;V_Fr;V_I], ...
    'VariableNames',{'Reaction','Km_mM','kcat_per_s','Enzyme_uM','Vmax_mM_per_s'});
disp(reaction_parameters); %[output:9b87ef26]
reaction_parameters_2 = table( ...
    {'r_S_2';'r_Sr_2';'r_F_2';'r_I_2';'r_Fr_2'}, ...
    [KM_S_2;KM_Sr_2;KM_F_2;KM_I_2;KM_Fr_2], ...
    [kcat_S_2;kcat_Sr_2;kcat_F_2;kcat_I_2;kcat_Fr_2], ...
    1e3*[E_S_2;E_Sr_2;E_F_2;E_I_2;E_Fr_2], ...
    [V_S_2;V_Sr_2;V_F_2;V_I_2;V_Fr_2], ...
    'VariableNames',{'Reaction','Km_mM','kcat_per_s','Enzyme_uM','Vmax_mM_per_s'});
disp(reaction_parameters_2); %[output:50576854]
%%
%[text] ## 6. Block 0: design concentrations, buffered cosubstrates and capacities
%[text] Concentration targets \[mM\] and turnover numbers are illustrative, not measurements.
tau_B0   = 30;                                   % response time of each Block 0 pool [s]
pool_ref = (j_S_ref+j_F_ref)*tau_B0/1.1;         % reference concentration that gives tau_B0
cAMP_ref = pool_ref; AMP_ref = pool_ref; adn_ref = pool_ref; r1p_ref = pool_ref; uri_ref = pool_ref;
K_EV_AC = 10*vesicles(row,1);            % activation constant in DATASET EV units, not mM
m_ATP_B0 = 2; m_Pi_B0 = 1; m_uracil_B0 = 0.05; m_dUTP_B0 = 0.05;
Km_ADNCYC_ATP = 0.2;
Km_PDE1_cAMP = 10*cAMP_ref;
Km_NTD7_AMP = 10*AMP_ref;
Km_PUNP1_adn = 10*adn_ref;    Km_PUNP1_Pi = 0.1;
Km_PYNP2r_r1p = 10*r1p_ref;   Km_PYNP2r_uracil = 0.005;
Km_r1156_uri = 10*uri_ref;    Km_r1156_dUTP = 0.005;
kcat_ADNCYC = 100; kcat_PDE1 = 100; kcat_NTD7 = 100;
kcat_PUNP1 = 100; kcat_PYNP2r = 100; kcat_r1156 = 100;

% Buffered cosubstrates enter as constant saturation fractions.
ATP_fraction    = m_ATP_B0/(Km_ADNCYC_ATP+m_ATP_B0);
Pi_fraction     = m_Pi_B0/(Km_PUNP1_Pi+m_Pi_B0);
uracil_fraction = m_uracil_B0/(Km_PYNP2r_uracil+m_uracil_B0);
dUTP_fraction   = m_dUTP_B0/(Km_r1156_dUTP+m_dUTP_B0);

% The supply of UMP equals what r_S and r_F withdraw at m_in_target.
J_B0_ref = j_S_ref+j_F_ref;
EV_activity_ref = vesicles(row,1)/(K_EV_AC+vesicles(row,1));
V_ADNCYC = J_B0_ref/(EV_activity_ref*ATP_fraction);
V_PDE1   = J_B0_ref/(cAMP_ref/(Km_PDE1_cAMP+cAMP_ref));
V_NTD7   = J_B0_ref/(AMP_ref/(Km_NTD7_AMP+AMP_ref));
V_PUNP1  = J_B0_ref/((adn_ref/(Km_PUNP1_adn+adn_ref))*Pi_fraction);
V_PYNP2r = J_B0_ref/((r1p_ref/(Km_PYNP2r_r1p+r1p_ref))*uracil_fraction);
V_r1156  = J_B0_ref/((uri_ref/(Km_r1156_uri+uri_ref))*dUTP_fraction);

block0_parameters = table( ...
    {'ADNCYC (assumed EV control)';'PDE1';'NTD7';'PUNP1';'PYNP2r (reverse)';'r1156'}, ...
    [Km_ADNCYC_ATP;Km_PDE1_cAMP;Km_NTD7_AMP;Km_PUNP1_adn;Km_PYNP2r_r1p;Km_r1156_uri], ...
    [kcat_ADNCYC;kcat_PDE1;kcat_NTD7;kcat_PUNP1;kcat_PYNP2r;kcat_r1156], ...
    1e3*[V_ADNCYC/kcat_ADNCYC;V_PDE1/kcat_PDE1;V_NTD7/kcat_NTD7; ...
         V_PUNP1/kcat_PUNP1;V_PYNP2r/kcat_PYNP2r;V_r1156/kcat_r1156], ...
    [V_ADNCYC;V_PDE1;V_NTD7;V_PUNP1;V_PYNP2r;V_r1156], ...
    'VariableNames',{'Reaction','Km_mM','kcat_per_s','Enzyme_uM','Vmax_mM_per_s'});
disp(block0_parameters); %[output:18d412ca]
%%
%[text] ## 7. Simulation: starting equilibrium, then explicit Euler
% Column 1 of every array is the analysed distance (row); the other columns
% are the remaining distances of the UMP figure, with the same enzymes.
idx = unique(round(linspace(1,size(vesicles,1),min(3,size(vesicles,1)))));
traces = unique([row idx],'stable');
nT = numel(traces);
m_cAMP = zeros(N,nT); m_AMP = zeros(N,nT); m_adn = zeros(N,nT);
m_r1p = zeros(N,nT);  m_uri = zeros(N,nT); m_in = zeros(N,nT);
m_S = zeros(N,nT);    m_F = zeros(N,nT);   m_d1 = zeros(N,nT);
v_r1156 = zeros(N,nT); v_S = zeros(N,nT);  v_Sr = zeros(N,nT);
v_F = zeros(N,nT);    v_Fr = zeros(N,nT);  v_I = zeros(N,nT);  v_load = zeros(N,nT);
m_S2 = zeros(N,nT);   m_d2 = zeros(N,nT);
v_S_2 = zeros(N,nT); v_Sr_2 = zeros(N,nT); v_F_2 = zeros(N,nT); v_I_2 = zeros(N,nT); v_Fr_2 = zeros(N,nT);
load_of = @(y) consume*(V_S_2*y/(Kx_S_2+y)+V_F_2*y/(Kx_F_2+y));   % what D2 withdraws from m_d1
root_options = optimset('Display','off','TolX',realmin);

for c = 1:nT
    EV = vesicles(traces(c),:).';
    assert(all(isfinite(EV)) && all(EV >= 0),'Each trace must be finite and nonnegative.');

    % ---------- starting equilibrium for the first EV sample ----------
    J0 = V_ADNCYC*EV(1)/(K_EV_AC+EV(1))*ATP_fraction;     % flux through the adapter
    if J0 > 0                                             % (no input: empty pools are the equilibrium)
        % Block 0: each pool carries the same flux J0.
        assert(J0 < V_PDE1 && J0 < V_NTD7 && J0 < V_PUNP1*Pi_fraction && ...
            J0 < V_PYNP2r*uracil_fraction && J0 < V_r1156*dUTP_fraction, ...
            'Block 0 has no finite equilibrium: the source flux exceeds an adapter capacity.');
        m_cAMP(1,c) = Km_PDE1_cAMP*J0/(V_PDE1-J0);
        m_AMP(1,c)  = Km_NTD7_AMP*J0/(V_NTD7-J0);
        m_adn(1,c)  = Km_PUNP1_adn*J0/(V_PUNP1*Pi_fraction-J0);
        m_r1p(1,c)  = Km_PYNP2r_r1p*J0/(V_PYNP2r*uracil_fraction-J0);
        m_uri(1,c)  = Km_r1156_uri*J0/(V_r1156*dUTP_fraction-J0);

        % UMP: supply J0 = withdrawal by r_S and r_F.
        assert(J0 < V_S+V_F,'Block 0 supply exceeds the capacity of r_S and r_F.');
        UMP_balance = @(u) V_S*u/(KM_S+u)+V_F*u/(KM_F+u)-J0;
        u_upper = 2*max(KM_S,KM_F)*J0/(V_S+V_F-J0);
        m_in(1,c) = fzero(UMP_balance,[0 u_upper],root_options);
        j_S0 = V_S*m_in(1,c)/(KM_S+m_in(1,c));
        j_F0 = V_F*m_in(1,c)/(KM_F+m_in(1,c));

        % Slow memory: r_Sr carries the slow flux.
        assert(j_S0 < V_Sr,'No finite slow-memory equilibrium: r_Sr is too small.');
        m_S(1,c) = KM_Sr*j_S0/(V_Sr-j_S0);

        % Output and fast memory. For a trial output y:
        %   v_I = j_S0 - load_of(y)     (output balance)
        %   v_Fr = j_F0 - v_I -> m_F    (fast-memory balance)
        % and y is the root of  V_I*m_F/(KM_I+m_F)*y/(KM_I_Y+y) = v_I.
        assert(j_F0 > j_S0,'The fast branch must carry more flux than the slow one (r_I draws from both).');
        vI_of  = @(y) j_S0-load_of(y);
        mF_of  = @(y) KM_Fr*(j_F0-vI_of(y))/(V_Fr-(j_F0-vI_of(y)));
        output_balance = @(y) V_I*mF_of(y)/(KM_I+mF_of(y))*y/(KM_I_Y+y)-vI_of(y);
        y_upper = 1e-6*KM_I_Y;
        while true
            assert(V_Fr > j_F0-vI_of(y_upper),'No finite fast-memory equilibrium: r_Fr is too small.');
            if output_balance(y_upper) >= 0, break; end
            y_upper = 2*y_upper;
            assert(y_upper < 1e6*KM_I_Y, ...
                'r_I cannot remove the slow flux and the output has no equilibrium: increase E_I.');
        end
        m_d1(1,c) = fzero(output_balance,[0 y_upper],root_options);
        m_F(1,c)  = mF_of(m_d1(1,c));

        % Differentiator 2. For a trial output z:
        %   v_I_2 = j_F_2 - v_Fr_2(z)            (output balance)
        %   v_Sr_2 = j_S_2 - v_I_2 -> m_S2   (memory balance)
        % and z is the root of  V_I_2*m_S2/(KM_I_2+m_S2)*z/(KM_I_2_Y+z) = v_I_2.
        if connect_D2
            j_F_2_0 = V_F_2*m_d1(1,c)/(Kx_F_2+m_d1(1,c));
            j_S_2_0 = V_S_2*m_d1(1,c)/(Kx_S_2+m_d1(1,c));
            vI_2_of = @(z) j_F_2_0-V_Fr_2*z/(KM_Fr_2+z);
            S2_of  = @(z) KM_Sr_2*(j_S_2_0-vI_2_of(z))/(V_Sr_2-(j_S_2_0-vI_2_of(z)));
            balance_2 = @(z) V_I_2*S2_of(z)/(KM_I_2+S2_of(z))*z/(KM_I_2_Y+z)-vI_2_of(z);
            z_upper = 1e-6*KM_I_2_Y;
            while true
                assert(V_Sr_2 > j_S_2_0-vI_2_of(z_upper),'No finite D2 memory equilibrium: r_Sr_2 is too small.');
                if balance_2(z_upper) >= 0, break; end
                z_upper = 2*z_upper;
                assert(z_upper < 1e6*KM_I_2_Y,'r_I_2 cannot remove the direct flux: m_d2 has no equilibrium; increase E_I_2 or cleanup_2.');
            end
            m_d2(1,c) = fzero(balance_2,[0 z_upper],root_options);
            m_S2(1,c) = S2_of(m_d2(1,c));
        end
    end

    % ---------- time stepping ----------
    for n = 1:N
        % Block 0
        v_ADNCYC = V_ADNCYC*EV(n)/(K_EV_AC+EV(n))*ATP_fraction;                      % ATP -> cAMP
        v_PDE1   = V_PDE1*m_cAMP(n,c)/(Km_PDE1_cAMP+m_cAMP(n,c));                    % cAMP -> AMP
        v_NTD7   = V_NTD7*m_AMP(n,c)/(Km_NTD7_AMP+m_AMP(n,c));                       % AMP -> adenosine
        v_PUNP1  = V_PUNP1*m_adn(n,c)/(Km_PUNP1_adn+m_adn(n,c))*Pi_fraction;         % adenosine -> ribose-1-P
        v_PYNP2r = V_PYNP2r*m_r1p(n,c)/(Km_PYNP2r_r1p+m_r1p(n,c))*uracil_fraction;   % ribose-1-P -> uridine
        v_r1156(n,c) = V_r1156*m_uri(n,c)/(Km_r1156_uri+m_uri(n,c))*dUTP_fraction;   % uridine -> UMP

        % Differentiator 1
        v_S(n,c)    = V_S*m_in(n,c)/(KM_S+m_in(n,c));                                % m_in -> m_S
        v_Sr(n,c)   = V_Sr*m_S(n,c)/(KM_Sr+m_S(n,c));                                % m_S  -> m_d1
        v_F(n,c)    = V_F*m_in(n,c)/(KM_F+m_in(n,c));                                % m_in -> m_F
        v_Fr(n,c)   = V_Fr*m_F(n,c)/(KM_Fr+m_F(n,c));                                % m_F  -> products
        v_I(n,c)    = V_I*m_F(n,c)/(KM_I+m_F(n,c))*m_d1(n,c)/(KM_I_Y+m_d1(n,c));     % m_F + m_d1 -> products

        % Differentiator 2
        v_F_2(n,c)  = V_F_2*m_d1(n,c)/(Kx_F_2+m_d1(n,c));                               % (m_d1) -> m_d2
        v_S_2(n,c)  = V_S_2*m_d1(n,c)/(Kx_S_2+m_d1(n,c));                               % (m_d1) -> m_S2
        v_Sr_2(n,c) = V_Sr_2*m_S2(n,c)/(KM_Sr_2+m_S2(n,c));                          % m_S2 -> products
        v_I_2(n,c)  = V_I_2*m_S2(n,c)/(KM_I_2+m_S2(n,c))*m_d2(n,c)/(KM_I_2_Y+m_d2(n,c));% m_S2 + m_d2 -> products
        v_Fr_2(n,c) = V_Fr_2*m_d2(n,c)/(KM_Fr_2+m_d2(n,c));                              % m_d2 -> products
        v_load(n,c) = consume*(v_F_2(n,c)+v_S_2(n,c));                               % load on m_d1 (0 if not consumed)
        if n == N, break; end

        % Explicit Euler
        dt = t(n+1)-t(n);
        m_cAMP(n+1,c) = m_cAMP(n,c)+dt*(v_ADNCYC-v_PDE1);
        m_AMP(n+1,c)  = m_AMP(n,c) +dt*(v_PDE1-v_NTD7);
        m_adn(n+1,c)  = m_adn(n,c) +dt*(v_NTD7-v_PUNP1);
        m_r1p(n+1,c)  = m_r1p(n,c) +dt*(v_PUNP1-v_PYNP2r);
        m_uri(n+1,c)  = m_uri(n,c) +dt*(v_PYNP2r-v_r1156(n,c));
        m_in(n+1,c)   = m_in(n,c)  +dt*(v_r1156(n,c)-v_S(n,c)-v_F(n,c));
        m_S(n+1,c)    = m_S(n,c)   +dt*(v_S(n,c)-v_Sr(n,c));
        m_F(n+1,c)    = m_F(n,c)   +dt*(v_F(n,c)-v_Fr(n,c)-v_I(n,c));
        m_d1(n+1,c)   = m_d1(n,c)  +dt*(v_Sr(n,c)-v_I(n,c)-v_load(n,c));
        % m_d2 is advanced implicitly: in the threshold regime its removal by
        % r_I_2 is very steep near zero and an explicit step would overshoot.
        % With A = rate of r_I_2 at full saturation in m_d2 and c_R the
        % first-order coefficient of r_Fr_2, the new value z solves
        %   z*(1+dt*c_R) + dt*A*z/(KM_I_2_Y+z) = m_d2 + dt*v_F_2   (z > 0).
        A_I2 = V_I_2*m_S2(n,c)/(KM_I_2+m_S2(n,c));
        c_R  = V_Fr_2/(KM_Fr_2+m_d2(n,c));
        qa = 1+dt*c_R;  qB = m_d2(n,c)+dt*v_F_2(n,c);
        qb = qa*KM_I_2_Y+dt*A_I2-qB;
        qd = sqrt(qb^2+4*qa*qB*KM_I_2_Y);
        if qb > 0
            m_d2(n+1,c) = 2*qB*KM_I_2_Y/(qb+qd);
        else
            m_d2(n+1,c) = (qd-qb)/(2*qa);
        end
        vI2_step = A_I2*m_d2(n+1,c)/(KM_I_2_Y+m_d2(n+1,c));     % r_I_2 over this step
        m_S2(n+1,c)   = m_S2(n,c)  +dt*(v_S_2(n,c)-v_Sr_2(n,c)-vI2_step);
        pools = [m_S2(n+1,c),m_d2(n+1,c), ...
                 m_cAMP(n+1,c),m_AMP(n+1,c),m_adn(n+1,c),m_r1p(n+1,c),m_uri(n+1,c), ...
                 m_in(n+1,c),m_S(n+1,c),m_F(n+1,c),m_d1(n+1,c)];
        assert(all(isfinite(pools)) && all(pools >= 0), ...
            'Invalid Euler step at n = %d (distance row %d); reduce dt0.',n,traces(c));
    end
end
%%
%[text] ## 8. Diagnostics at the starting equilibrium (analysed distance)
u0 = m_in(1,1);  S0 = m_S(1,1);  F0 = m_F(1,1);  Y0 = m_d1(1,1);
k_in  = V_S*KM_S/(KM_S+u0)^2+V_F*KM_F/(KM_F+u0)^2;                          % UMP pool
k_mS  = V_Sr*KM_Sr/(KM_Sr+S0)^2;                                            % slow memory
k_mF  = V_Fr*KM_Fr/(KM_Fr+F0)^2+V_I*Y0/(KM_I_Y+Y0)*KM_I/(KM_I+F0)^2;        % fast memory
k_d1  = V_I*F0/(KM_I+F0)*KM_I_Y/(KM_I_Y+Y0)^2 ...                           % output
        +consume*(V_S_2*Kx_S_2/(Kx_S_2+Y0)^2+V_F_2*Kx_F_2/(Kx_F_2+Y0)^2);
fprintf('\nBasal levels [mM]: m_in %.4g, m_S %.4g, m_F %.4g, m_d1 %.4g\n',u0,S0,F0,Y0); %[output:8e587f65]
fprintf('Saturation: r_S %.0f%%, r_F %.0f%%, r_Sr %.0f%%, r_Fr %.0f%%, r_I %.0f%% (m_F) and %.0f%% (m_d1)\n', ... %[output:group:186f8981] %[output:9ee844f4]
    100*u0/(KM_S+u0),100*u0/(KM_F+u0),100*S0/(KM_Sr+S0),100*F0/(KM_Fr+F0), ... %[output:9ee844f4]
    100*F0/(KM_I+F0),100*Y0/(KM_I_Y+Y0)); %[output:group:186f8981] %[output:9ee844f4]
fprintf('Local time constants [s]: UMP %.3g, slow memory %.3g, fast memory %.3g, output %.3g\n', ... %[output:group:849148d7] %[output:6bbd5d9f]
    1/k_in,1/k_mS,1/k_mF,1/k_d1); %[output:group:849148d7] %[output:6bbd5d9f]
fprintf('Output removal at rest: r_I %.0f%%, load %.0f%%n', ... %[output:group:13977935] %[output:46885758]
    100*v_I(1,1)/(v_I(1,1)+v_load(1,1)),100*v_load(1,1)/(v_I(1,1)+v_load(1,1))); %[output:group:13977935] %[output:46885758]
if dt0*max([k_in,k_mS,k_mF,k_d1]) > 1
    warning('dt0 = %.3g s is too coarse for the fastest pool (%.3g 1/s); reduce dt0.',dt0,max([k_in,k_mS,k_mF,k_d1]));
end

if connect_D2 %[output:group:19e2f3df]
    M0 = m_S2(1,1);  Z0 = m_d2(1,1);
    k_S2 = V_Sr_2*KM_Sr_2/(KM_Sr_2+M0)^2+V_I_2*Z0/(KM_I_2_Y+Z0)*KM_I_2/(KM_I_2+M0)^2;      % D2 memory
    k_d2 = V_I_2*M0/(KM_I_2+M0)*KM_I_2_Y/(KM_I_2_Y+Z0)^2+V_Fr_2*KM_Fr_2/(KM_Fr_2+Z0)^2;         % D2 output
    fprintf('\nD2 basal levels [mM]: m_S2 %.4g, m_d2 %.4g  (m_d2/m_d1 = %.3g)\n',M0,Z0,Z0/Y0); %[output:3ce4edbe]
    fprintf('D2 saturation: r_Sr_2 %.0f%%, r_I_2 %.0f%% (m_S2) and %.0f%% (m_d2)\n', ... %[output:655d44d8]
        100*M0/(KM_Sr_2+M0),100*M0/(KM_I_2+M0),100*Z0/(KM_I_2_Y+Z0)); %[output:655d44d8]
    fprintf('D2 local time constants [s]: memory %.3g, output %.3g\n',1/k_S2,1/k_d2); %[output:02a6b9bc]
    if ~consuming_2
        % The ideal activation law ignores the m_d1 that sits bound on the two
        % source enzymes. It is negligible only if this ratio is well below 1.
        fprintf('D2 connection: m_d1 bound on r_F_2 and r_S_2 / free m_d1 = %.3g  (ideal law needs << 1)\n', ...
            (E_F_2+E_S_2)/(K_A_2+Y0));
    end
    d2_deviation = m_d2(:,1)-Z0;
    slope_d1 = gradient(m_d1(:,1),t);
    fprintf('D2 output: rest %.3g mM, peak %.3g mM (%.3g times the rest), lowest %.3g mM, last %.3g mM\n', ... %[output:38ed3702]
        Z0,max(m_d2(:,1)),max(m_d2(:,1))/Z0,min(m_d2(:,1)),m_d2(end,1)); %[output:38ed3702]
    if dt0*k_S2 > 1                      % (m_d2 itself is advanced implicitly)
        warning('dt0 = %.3g s is too coarse for the D2 memory (%.3g 1/s); reduce dt0.',dt0,k_S2);
    end
end %[output:group:19e2f3df]

% Peak of the falling input slope against the peak of the output deviation.
negativeSlope = -gradient(m_in(:,1),t);
d1_deviation  = m_d1(:,1)-Y0;
[~,iSlope] = max(negativeSlope);
[~,iOut]   = max(d1_deviation);
fprintf('Input falling-slope peak at %.3g s; output peak at %.3g s; lag %.3g s.\n', ... %[output:group:7748bb4c] %[output:8aa75015]
    t(iSlope),t(iOut),t(iOut)-t(iSlope)); %[output:group:7748bb4c] %[output:8aa75015]
%%
%[text] ## 9. Figures
% 1. UMP at the plotted distances, with its slope in the first seconds.
figure; %[output:22880902]
plot(t/60,m_in,'LineWidth',2); grid on; %[output:22880902]
xlabel('Time [min]','Interpreter','latex'); %[output:22880902]
ylabel('m_{in} [mM]','Interpreter','latex'); %[output:22880902]
labels = arrayfun(@(i) sprintf('d = %.3g um',dist(i)*1e6),traces,'UniformOutput',false);
legend(labels,'Location','southwest','NumColumns',nT); %[output:22880902]
set(gca,'FontSize',fontsize+5); %[output:22880902]
positionMain = get(gca,'Position');
inset = axes('Position',[positionMain(1)+0.43 positionMain(2)+0.42 0.30 0.26]); %[output:22880902]
total = min(round(50/dt0),N-1);
slope_UMP = diff(m_in,1,1)./diff(t);
plot(t(1:total),slope_UMP(1:total,:),'LineWidth',1.5); %[output:22880902]
xlabel('Time [s]'); ylabel('UMP slope [mM/s]'); grid on; %[output:22880902]
set(inset,'FontSize',max(8,fontsize-2)); %[output:22880902] %[output:24b22ca7]

% 2. Differentiator input (analysed distance).
figure; %[output:69744b43]
plot(t/60,m_in(:,1),'LineWidth',2.5); grid on; %[output:69744b43]
xlabel('Time [min]','Interpreter','latex'); %[output:69744b43]
ylabel('$[m_\mathrm{in}]$ mM','Interpreter','latex'); %[output:69744b43]
xlim([0,min(50,t(end)/60)]); %[output:69744b43]
legend(strcat('$d =', sprintf('%.3g',dist(row)*1e6),'\mu$m'),'Location','northeast','Interpreter','latex'); %[output:69744b43]
set(gca,'FontSize',fontsize+12); %[output:69744b43]

% 3. Differentiator output.
figure; %[output:456aca03]
plot(t/60,m_d1(:,1),'LineWidth',2.5); grid on; %[output:456aca03]
xlabel('Time [min]','Interpreter','latex'); %[output:456aca03]
ylabel('$[m_{\mathrm{D}1}]$ mM','Interpreter','latex'); %[output:456aca03]
xlim([0,min(50,t(end)/60)]); %[output:456aca03]
set(gca,'FontSize',fontsize+12); %[output:456aca03]

% 3b. Second differentiator output.
if connect_D2 %[output:group:9049a1c2]
    figure; %[output:2e19b20b]
    plot(t/60,m_d2(:,1),'LineWidth',2.5); grid on; %[output:2e19b20b]
    xlabel('Time [min]','Interpreter','latex'); %[output:2e19b20b]
    ylabel('$[m_{\mathrm{D}2}]$ mM','Interpreter','latex'); %[output:2e19b20b]
    xlim([0,min(50,t(end)/60)]); %[output:2e19b20b]
    set(gca,'FontSize',fontsize+12); %[output:2e19b20b]
end %[output:group:9049a1c2]

% 4. The two memories and the output.
figure; %[output:574ddcb1]
plot(t/60,[m_S(:,1),m_F(:,1),m_d1(:,1)],'LineWidth',2); grid on; %[output:574ddcb1]
xlabel('Time [min]'); ylabel('Concentration [mM]'); %[output:574ddcb1]
legend('m_S (slow memory)','m_F (fast memory)','m_{d1} (output)','Location','best'); %[output:574ddcb1]
xlim([0,min(5,t(end)/60)]); %[output:574ddcb1]
set(gca,'FontSize',fontsize); %[output:574ddcb1]

% 5. What produces and what removes the output.
figure; %[output:9f1ec0ef]
plot(t/60,[v_Sr(:,1),v_I(:,1),v_load(:,1)],'LineWidth',2); grid on; %[output:9f1ec0ef]
xlabel('Time [min]'); ylabel('Rate [mM/s]'); %[output:9f1ec0ef]
legend('r_{Sr}: production of m_{d1}','r_I: cancellation','load','Location','best'); %[output:9f1ec0ef]
xlim([0,min(5,t(end)/60)]); %[output:9f1ec0ef]
set(gca,'FontSize',fontsize); %[output:9f1ec0ef]

% 6. Output deviation against the falling slope of the input.
figure; %[output:75e809a9]
yyaxis left;  plot(t/60,d1_deviation,'LineWidth',1.5); ylabel('m_{d1} - basal [mM]'); %[output:75e809a9]
yyaxis right; plot(t/60,negativeSlope,'--','LineWidth',1.5); ylabel('-dm_{in}/dt [mM/s]'); %[output:75e809a9]
xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:75e809a9]
legend('Output deviation','Input falling slope','Location','best'); %[output:75e809a9]
