legend(["Output deviation", "Input falling slope"], "Position", [0.3567 0.7845 0.4622, 0.1780]) %[output:75e809a9]

% 7. Second differentiator: output deviation against the slope of its input m_d1.
if connect_D2 %[output:group:30ca31ff]
    figure; %[output:115f8878]
    yyaxis left;  plot(t/60,d2_deviation,'LineWidth',1.5); ylabel('m_{d2} - basal [mM]'); %[output:115f8878]
    yyaxis right; plot(t/60,slope_d1,'--','LineWidth',1.5); ylabel('dm_{d1}/dt [mM/s]'); %[output:115f8878]
    xlabel('Time [min]'); xlim([0,min(150,t(end)/60)]); grid on; %[output:115f8878]
    legend('D2 output deviation','Slope of m_{d1}','Location','best'); %[output:115f8878]
    set(gca,'FontSize',fontsize); %[output:115f8878]
end %[output:group:30ca31ff]
